update zjudg_user_address
set contact_name = #{contactName}, contact_phone = #{contactPhone}, city_id = #{cityId},
    region = #{region}, detail = #{detail}, label = #{label}, is_default = #{isDefault},
    status = #{status}, update_by = #{updateBy}, update_time = sysdate(), remark = #{remark}
where address_id = #{addressId} and user_id = #{userId}
